function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function getNumber(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function normalize(value) {
  return getString(value)
    .toLowerCase()
    .replaceAll("ı", "i")
    .replaceAll("ğ", "g")
    .replaceAll("ü", "u")
    .replaceAll("ş", "s")
    .replaceAll("ö", "o")
    .replaceAll("ç", "c")
    .trim();
}

function average(numbers) {
  const valid = numbers.filter((value) => value !== null && Number.isFinite(value));
  if (valid.length === 0) return null;

  return Math.round(
    (valid.reduce((sum, value) => sum + value, 0) / valid.length) * 100,
  ) / 100;
}

function getWeekDates() {
  const now = new Date();
  const day = now.getDay();
  const diffToMonday = day === 0 ? -6 : 1 - day;

  const monday = new Date(now);
  monday.setDate(now.getDate() + diffToMonday);

  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);

  return {
    start: monday.toISOString().slice(0, 10),
    end: sunday.toISOString().slice(0, 10),
    key: `${monday.toISOString().slice(0, 10)}_${sunday.toISOString().slice(0, 10)}`,
  };
}

function isPresent(value) {
  const status = normalize(value);
  return status === "geldi" || status === "gec geldi" || status === "geç geldi";
}

function riskCount(predictions, riskName) {
  const wanted = normalize(riskName);
  return predictions.filter((prediction) => normalize(prediction.fields.Risk_Seviyesi) === wanted).length;
}

function getTeacherName(users, teacherId) {
  const teacher = users.find((user) => user.id === teacherId);
  return getString(teacher?.fields?.Ad_Soyad) || "Öğretmen";
}

function getTeacherEmail(users, teacherId) {
  const teacher = users.find((user) => user.id === teacherId);
  return getString(teacher?.fields?.Eposta);
}

const classes = getRecords("GET Classes");
const users = getRecords("GET Users");
const memberships = getRecords("GET Memberships");
const grades = getRecords("GET Grades");
const assignments = getRecords("GET Assignments");
const submissions = getRecords("GET Submissions");
const attendance = getRecords("GET Attendance");
const predictions = getRecords("GET Predictions");
const summaries = getRecords("GET Student Summaries");
const riskSignals = getRecords("GET Risk Signals");
const existingReports = getRecords("GET Existing Weekly Assistant Reports");

const week = getWeekDates();

const existingReportText = existingReports
  .map((report) => getString(report.fields.Rapor_Metni))
  .join("\n");

const output = [];

for (const classRecord of classes) {
  const classId = classRecord.id;
  const teacherId = asLinks(classRecord.fields.Ogretmen)[0];

  if (!teacherId) continue;

  const teacherName = getTeacherName(users, teacherId);
  const teacherEmail = getTeacherEmail(users, teacherId);

  if (!teacherEmail) continue;

  const className =
    getString(classRecord.fields.Sinif_Adi) ||
    getString(classRecord.fields.Ders_Adi) ||
    "Sınıf";

  const trackingCode = `AI_ASISTAN_HAFTALIK_ONERI:${week.key}:SINIF:${classId}:OGRETMEN:${teacherId}`;

  if (existingReportText.includes(trackingCode)) {
    continue;
  }

  const classMemberships = memberships.filter((membership) =>
    asLinks(membership.fields.Sinif).includes(classId),
  );

  const activeStudentMemberships = classMemberships.filter((membership) => {
    const role = normalize(membership.fields.Uyelik_Rolu);
    const status = normalize(membership.fields.Durum);
    return role === "ogrenci" && status === "aktif";
  });

  const classGrades = grades.filter((grade) =>
    asLinks(grade.fields.Sinif).includes(classId),
  );

  const classGradeAverage = average(
    classGrades.map((grade) => getNumber(grade.fields.Puan)),
  );

  const classAssignments = assignments.filter((assignment) =>
    asLinks(assignment.fields.Sinif).includes(classId),
  );

  const classSubmissions = submissions.filter((submission) =>
    asLinks(submission.fields.Sinif).includes(classId),
  );

  const deliveryRate =
    classAssignments.length > 0 && activeStudentMemberships.length > 0
      ? Math.round(
          (classSubmissions.length /
            (classAssignments.length * activeStudentMemberships.length)) *
            10000,
        ) / 100
      : null;

  const classAttendance = attendance.filter((record) =>
    asLinks(record.fields.Sinif).includes(classId),
  );

  const presentCount = classAttendance.filter((record) =>
    isPresent(record.fields.Durum),
  ).length;

  const attendanceRate =
    classAttendance.length > 0
      ? Math.round((presentCount / classAttendance.length) * 10000) / 100
      : null;

  const classPredictions = predictions.filter((prediction) =>
    asLinks(prediction.fields.Sinif).includes(classId),
  );

  const lowRisk = riskCount(classPredictions, "Düşük");
  const mediumRisk = riskCount(classPredictions, "Orta");
  const highRisk = riskCount(classPredictions, "Yüksek");
  const criticalRisk = riskCount(classPredictions, "Kritik");

  const highRiskStudents = classPredictions
    .filter((prediction) => {
      const risk = normalize(prediction.fields.Risk_Seviyesi);
      return risk === "yuksek" || risk === "yüksek" || risk === "kritik";
    })
    .map((prediction) => {
      const studentId = asLinks(prediction.fields.Ogrenci)[0];
      const student = users.find((user) => user.id === studentId);
      return {
        name: getString(student?.fields?.Ad_Soyad) || "Öğrenci",
        risk: getString(prediction.fields.Risk_Seviyesi),
        summary:
          getString(prediction.fields.Ozet) ||
          getString(prediction.fields.Ogretmene_Gosterilecek),
      };
    });

  const classSummaries = summaries.filter((summary) =>
    asLinks(summary.fields.Sinif).includes(classId),
  );

  const classRiskSignals = riskSignals.filter((signal) =>
    asLinks(signal.fields.Sinif).includes(classId),
  );

  const commonRiskReasons = classRiskSignals
    .map((signal) => getString(signal.fields.Sinyal_Turu) || getString(signal.fields.Sinyal_Adi))
    .filter(Boolean)
    .slice(0, 6)
    .join(", ");

  const dataSummary = [
    `Sınıf: ${className}`,
    `Öğretmen: ${teacherName}`,
    `Hafta: ${week.start} - ${week.end}`,
    `Aktif öğrenci sayısı: ${activeStudentMemberships.length}`,
    `Sınıf not ortalaması: ${classGradeAverage === null ? "Yok" : classGradeAverage}`,
    `Ödev sayısı: ${classAssignments.length}`,
    `Toplam teslim kaydı: ${classSubmissions.length}`,
    `Tahmini ödev teslim oranı: ${deliveryRate === null ? "Yok" : `${deliveryRate}%`}`,
    `Yoklama kaydı: ${classAttendance.length}`,
    `Yoklama katılım oranı: ${attendanceRate === null ? "Yok" : `${attendanceRate}%`}`,
    `AI tahmin sayısı: ${classPredictions.length}`,
    `Düşük risk: ${lowRisk}`,
    `Orta risk: ${mediumRisk}`,
    `Yüksek risk: ${highRisk}`,
    `Kritik risk: ${criticalRisk}`,
    `Risk sinyali sayısı: ${classRiskSignals.length}`,
    `En yaygın risk nedenleri: ${commonRiskReasons || "Yok"}`,
    "",
    "Yüksek/Kritik riskteki öğrenciler:",
    highRiskStudents.length > 0
      ? highRiskStudents
          .map((student) => `${student.name} - ${student.risk} - ${student.summary || "-"}`)
          .join("\n")
      : "Yok",
    "",
    "Son öğrenci özetlerinden örnekler:",
    classSummaries
      .slice(0, 5)
      .map((summary) => getString(summary.fields.AI_Onerisi).slice(0, 350))
      .filter(Boolean)
      .join("\n---\n") || "Yok",
    "",
    `Takip kodu: ${trackingCode}`,
  ].join("\n");

  const aiPrompt = `
Sen AkıllıSınıf AI sisteminde çalışan öğretmen karar destek asistanısın.

Aşağıdaki haftalık sınıf verilerine göre öğretmene uygulanabilir ders ve sınıf yönetimi önerileri üret.

Veriler:
${dataSummary}

Kurallar:
- Türkçe yaz.
- Akademik, net ve öğretmen odaklı ol.
- Öğrenci isimlerini yalnızca bağlamda varsa kullan.
- 5-8 maddelik somut öneri ver.
- Gereksiz uzun yazma.
- Öğrenciyi suçlayıcı dil kullanma.
- Çıktıyı düz metin olarak ver; JSON gerekmez.
`;

  output.push({
    json: {
      trackingCode,
      classId,
      className,
      teacherId,
      teacherName,
      teacherEmail,
      weekStart: week.start,
      weekEnd: week.end,
      studentCount: activeStudentMemberships.length,
      lowRisk,
      mediumRisk,
      highRisk,
      criticalRisk,
      commonRiskReasons,
      dataSummary,
      aiPrompt,
    },
  });
}

return output;

