function getString(value) {
  return String(value || "").trim();
}

function tryParseJson(value) {
  if (typeof value !== "string") return value;

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

function findTextDeep(value, depth = 0) {
  if (depth > 8 || value === null || value === undefined) return "";

  const parsed = tryParseJson(value);

  if (typeof parsed === "string") {
    return parsed.trim();
  }

  if (Array.isArray(parsed)) {
    for (const item of parsed) {
      const found = findTextDeep(item, depth + 1);
      if (found) return found;
    }
    return "";
  }

  if (typeof parsed === "object") {
    const directCandidates = [
      parsed?.choices?.[0]?.message?.content,
      parsed?.body?.choices?.[0]?.message?.content,
      parsed?.data?.choices?.[0]?.message?.content,
      parsed?.response?.choices?.[0]?.message?.content,
      parsed?.message?.content,
      parsed?.content,
      parsed?.text,
      parsed?.answer,
      parsed?.output,
      parsed?.body,
      parsed?.data,
      parsed?.response,
    ];

    for (const candidate of directCandidates) {
      const found = findTextDeep(candidate, depth + 1);
      if (found) return found;
    }

    for (const key of Object.keys(parsed)) {
      const found = findTextDeep(parsed[key], depth + 1);
      if (found) return found;
    }
  }

  return "";
}

function buildEmailHtml({ teacherName, className, weekStart, weekEnd, reportText, trackingCode }) {
  return `
<div style="font-family:Arial,Helvetica,sans-serif;background:#f1f5f9;padding:32px;">
  <div style="max-width:720px;margin:auto;background:white;border-radius:24px;overflow:hidden;border:1px solid #e2e8f0;">
    <div style="background:#0f172a;color:white;padding:28px 32px;">
      <div style="font-size:12px;letter-spacing:4px;text-transform:uppercase;color:#bfdbfe;font-weight:700;">
        AkıllıSınıf AI
      </div>
      <h1 style="margin:12px 0 0;font-size:28px;line-height:1.2;color:#ffffff;">
        Haftalık AI Asistan Sınıf Önerileri
      </h1>
      <p style="margin:12px 0 0;color:#dbeafe;font-size:15px;line-height:1.6;">
        ${className} sınıfı için ${weekStart} - ${weekEnd} haftası önerileri.
      </p>
    </div>

    <div style="padding:32px;color:#0f172a;">
      <p style="margin:0 0 16px;font-size:16px;line-height:1.7;">
        Merhaba <strong>${teacherName}</strong>,
      </p>

      <div style="white-space:pre-wrap;line-height:1.7;font-size:15px;color:#334155;background:#f8fafc;border:1px solid #e2e8f0;border-radius:18px;padding:20px;">
${reportText}
      </div>

      <div style="margin-top:24px;padding:14px;border-radius:14px;background:#eff6ff;border:1px solid #bfdbfe;color:#1e40af;font-size:12px;">
        Sistem takip kodu: ${trackingCode}
      </div>
    </div>

    <div style="background:#f8fafc;padding:20px 32px;border-top:1px solid #e2e8f0;color:#64748b;font-size:12px;line-height:1.6;">
      AkıllıSınıf AI · Yapay Zekâ Destekli Sınıf Performans ve Erken Uyarı Sistemi
    </div>
  </div>
</div>
`;
}

const sourceItems = $items("Prepare Weekly Class Advice");
const aiItems = $items("OpenRouter Weekly Class Advice");

const output = [];

for (let index = 0; index < sourceItems.length; index += 1) {
  const source = sourceItems[index]?.json || {};
  const ai = aiItems[index]?.json || {};

  let aiText = findTextDeep(ai);

  if (!aiText || aiText.length < 20) {
    aiText = [
      "AI asistan yanıtı okunamadı; ancak sistem verileri başarıyla analiz edildi.",
      "",
      "Öncelikli öğretmen aksiyonları:",
      "- Risk seviyesi yüksek veya kritik olan öğrenciler için bireysel takip yapılmalı.",
      "- Ödev teslim oranı düşükse eksik ödevler için kısa teslim planı hazırlanmalı.",
      "- Yoklama kayıtları düzenli kontrol edilmeli.",
      "- Not ortalaması düşük öğrenciler için konu bazlı destek verilmelidir.",
    ].join("\n");
  }

  const reportText = [
    aiText,
    "",
    "Veri Özeti:",
    source.dataSummary,
    "",
    `Sistem takip kodu: ${source.trackingCode}`,
  ].join("\n");

  output.push({
    json: {
      fields: {
        Rapor_Adi: `${source.className} - AI Asistan Haftalık Önerileri`,
        Sinif: [source.classId],
        Ogretmen: [source.teacherId],
        Hafta_Baslangic: source.weekStart,
        Hafta_Bitis: source.weekEnd,
        Toplam_Ogrenci: source.studentCount,
        Dusuk_Risk_Sayisi: source.lowRisk,
        Orta_Risk_Sayisi: source.mediumRisk,
        Yuksek_Risk_Sayisi: source.highRisk,
        Kritik_Risk_Sayisi: source.criticalRisk,
        En_Yaygin_Risk_Nedeni: source.commonRiskReasons || "Belirgin risk nedeni yok",
        Rapor_Metni: reportText,
        Durum: "Tamamlandı",
      },
      notificationFields: {
        Bildirim_Basligi: "Haftalık AI asistan önerileri hazır",
        Alici: [source.teacherId],
        Sinif: [source.classId],
        Bildirim_Turu: "AI Asistan Önerisi",
        Mesaj: `${source.className} sınıfı için haftalık AI asistan önerileri hazırlandı.`,
        Onem_Derecesi: source.highRisk > 0 || source.criticalRisk > 0 ? "Yüksek" : "Orta",
        Okundu_Mu: false,
        Gonderildi_Mi: true,
        Kanal: "E-posta + Webhook",
      },
      emailTo: source.teacherEmail,
      emailSubject: `Haftalık AI sınıf önerileri: ${source.className}`,
      emailHtml: buildEmailHtml({
        teacherName: source.teacherName,
        className: source.className,
        weekStart: source.weekStart,
        weekEnd: source.weekEnd,
        reportText: aiText,
        trackingCode: source.trackingCode,
      }),
    },
  });
}

return output;
